/// A colour that follows the appearance between its light and dark value. The
/// app pins itself light, so today every one of these is its light value.
private func vvColor(_ light: UIColor, _ dark: UIColor) -> Color {
    Color(UIColor { $0.userInterfaceStyle == .dark ? dark : light })
}

