/// Durations in seconds, and the curves they run on.
enum VVMotion {
    /// Hover and colour changes.
    static let fast: Double = 0.15
    /// Something closing.
    static let quick: Double = 0.2
    /// Tabs, the rail, a panel moving.
    static let base: Double = 0.3
    /// A view arriving.
    static let slow: Double = 0.38
    /// A whole tab set changing.
    static let slower: Double = 0.55

    /// Things moving between two places.
    static func standard(_ duration: Double = base) -> Animation {
        .timingCurve(0.4, 0, 0.2, 1, duration: duration)
    }
    /// Things arriving: fast out, long settle.
    static func enter(_ duration: Double = base) -> Animation {
        .timingCurve(0.22, 1, 0.36, 1, duration: duration)
    }
    /// The shell and rail resizing (CSS `ease`).
    static func gentle(_ duration: Double = base) -> Animation {
        .timingCurve(0.25, 0.1, 0.25, 1, duration: duration)
    }
    /// A dragged row landing.
    static func settle(_ duration: Double = base) -> Animation {
        .timingCurve(0.25, 1, 0.5, 1, duration: duration)
    }
    /// A small spring past the mark.
    static func overshoot(_ duration: Double = base) -> Animation {
        .timingCurve(0.34, 1.56, 0.64, 1, duration: duration)
    }
}
